package com.wolfe.admin;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="staff_alerts", indexes=@Index(name="idx_staff_alert_created", columnList="created_at"))
public class StaffAlert { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,length=40) String type; @Column(nullable=false,length=200) String subject; @Column(nullable=false,length=2000) String message; @Column(nullable=false) Instant createdAt=Instant.now(); @Column(nullable=false) boolean acknowledged=false; protected StaffAlert(){} public StaffAlert(String type,String subject,String message){this.type=type;this.subject=subject;this.message=message;} public Long getId(){return id;} public String getType(){return type;} public String getSubject(){return subject;} public String getMessage(){return message;} public Instant getCreatedAt(){return createdAt;} public boolean isAcknowledged(){return acknowledged;} public void acknowledge(){acknowledged=true;} }
